// 1. Spatial Locality Optimization (C/C++ Row-major order)
#define N 512
int matrix[N][N];

// GOOD: Unit stride, high spatial locality
void optimal_traverse() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j]++; // Efficient cache line utilization
        }
    }
}

// POOR: Stride equals N, cache line thrashing possible
void poor_traverse() {
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            matrix[i][j]++; // New cache line likely loaded every iteration
        }
    }
}

// 2. Cache Blocking / Tiling (Temporal Locality for Matrix Ops)
#define M 1024
#define BLOCK_SIZE 32 // Tune for L1/L2 cache capacity

void blocked_matrix_multiply(float A[M][M], float B[M][M], float C[M][M]) {
    for (int kk = 0; kk < M; kk += BLOCK_SIZE) {
        for (int jj = 0; jj < M; jj += BLOCK_SIZE) {
            // Inner loops operate only on the loaded block
            for (int i = 0; i < M; i++) {
                for (int j = jj; j < jj + BLOCK_SIZE; j++) {
                    for (int k = kk; k < kk + BLOCK_SIZE; k++) {
                        C[i][j] += A[i][k] * B[k][j];
                    }}}}
}

// 3. Avoiding False Sharing (Cache Coherency Penalty)
#define CACHE_LINE_BYTES 64
// Uses C11 standard for memory alignment
struct _Alignas(CACHE_LINE_BYTES) AlignedCounter {
    long thread_local_count;
    // No explicit padding needed if struct size is exactly CACHE_LINE_BYTES
};

// If 'counters' array is used by different threads,
// each thread's access modification updates its own clean cache line.
AlignedCounter counters[8];
